package com.example.leavemanagement.contract;
import com.example.leavemanagement.auth.application.AccountUserDetailsService;import com.example.leavemanagement.people.api.AdminEmployeeController;import com.example.leavemanagement.people.application.*;import com.example.leavemanagement.shared.security.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.http.MediaType;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(AdminEmployeeController.class) @Import(SecurityConfiguration.class) class AdministrationConfigurationApiContractTest { @Autowired MockMvc mvc; @MockitoBean EmployeeAdministrationService service; @MockitoBean EmployeeAdministrationQueryService query; @MockitoBean CurrentActorProvider actors; @MockitoBean AuthenticationManager authentication; @MockitoBean AccountUserDetailsService users;
 @Test void creationRequiresPasswordAndRoles() throws Exception {mvc.perform(post("/api/admin/employees").with(user("u").roles("ADMINISTRATOR")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"employeeNumber\":\"E1\",\"displayName\":\"New\",\"email\":\"new@example.com\",\"login\":\"new\",\"roles\":[],\"active\":true}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));verifyNoInteractions(service);}
 @Test void administratorCreateDoesNotExposeCredentialFields() throws Exception {var v=new EmployeeAdministrationService.View(UUID.randomUUID(),"E1","New","new@example.com",null,null,Set.of("EMPLOYEE"),true,0);when(service.create(any())).thenReturn(v);mvc.perform(post("/api/admin/employees").with(user("u").roles("ADMINISTRATOR")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"employeeNumber\":\"E1\",\"displayName\":\"New\",\"email\":\"new@example.com\",\"login\":\"new\",\"initialPassword\":\"correct horse battery\",\"roles\":[\"EMPLOYEE\"],\"active\":true}" )).andExpect(status().isCreated()).andExpect(jsonPath("$.password").doesNotExist()).andExpect(jsonPath("$.initialPassword").doesNotExist());}
 @Test void nonAdministratorIsForbidden() throws Exception {mvc.perform(get("/api/admin/employees").with(user("u").roles("EMPLOYEE"))).andExpect(status().isForbidden());verifyNoInteractions(query);}
}
